<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{api,logout,type ApiResponse,type UserProfile}from'@whaashop/shared';import CustomerService from './components/CustomerService.vue';import PromotionShowcase from './components/PromotionShowcase.vue';import BrandLogo from './components/BrandLogo.vue';
const route=useRoute(),router=useRouter(),search=ref(''),loggedIn=ref(false),nickname=ref(''),avatarUrl=ref(''),menuOpen=ref(false),account=ref<HTMLElement>();const initial=computed(()=>nickname.value.trim().slice(0,1).toUpperCase()||'用');
async function refreshAccount(){loggedIn.value=!!localStorage.getItem('token');if(!loggedIn.value){nickname.value='';avatarUrl.value='';return}nickname.value=localStorage.getItem('nickname')||'商城用户';try{const{data}=await api.get<ApiResponse<UserProfile>>('/shop/profile');nickname.value=data.data.nickname||nickname.value;avatarUrl.value=data.data.avatarUrl||'';localStorage.setItem('nickname',nickname.value)}catch{avatarUrl.value=''}}
watch(()=>route.fullPath,()=>{search.value=String(route.query.q??'');menuOpen.value=false;refreshAccount()},{immediate:true});function submitSearch(){const q=search.value.trim();if(q)router.push({path:'/search',query:{q}})}function signOut(){logout();loggedIn.value=false;nickname.value='';avatarUrl.value='';menuOpen.value=false;router.push('/')}function outside(event:MouseEvent){if(menuOpen.value&&!account.value?.contains(event.target as Node))menuOpen.value=false}function keyboard(event:KeyboardEvent){if(event.key==='Escape')menuOpen.value=false}
onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',keyboard);window.addEventListener('profile-updated',refreshAccount)});onBeforeUnmount(()=>{document.removeEventListener('click',outside);document.removeEventListener('keydown',keyboard);window.removeEventListener('profile-updated',refreshAccount)});
</script>
<template><header><router-link class="logo" to="/"><BrandLogo tagline="SELECTED GOODS"/></router-link><form class="global-search" role="search" @submit.prevent="submitSearch"><span aria-hidden="true">⌕</span><input v-model="search" maxlength="80" aria-label="搜索商品" placeholder="搜索商品名称或描述"><button aria-label="提交搜索">搜索</button></form><nav><router-link to="/">商城首页</router-link><a href="/#categories">商品分类</a><router-link to="/cart">购物车</router-link><router-link to="/orders">我的订单</router-link><div v-if="loggedIn" ref="account" class="account-menu"><button class="account-trigger" type="button" :aria-expanded="menuOpen" aria-haspopup="menu" @click.stop="menuOpen=!menuOpen"><span class="header-avatar"><img v-if="avatarUrl" :src="avatarUrl" alt="用户头像"><b v-else>{{initial}}</b></span><span class="account-name">{{nickname}}</span><i :class="{open:menuOpen}">⌄</i></button><transition name="account-pop"><div v-if="menuOpen" class="account-dropdown" role="menu"><div class="account-summary"><span class="header-avatar large"><img v-if="avatarUrl" :src="avatarUrl" alt=""><b v-else>{{initial}}</b></span><div><strong>{{nickname}}</strong><small class="member-brand"><BrandLogo compact/>橙心会员</small></div></div><router-link to="/profile" role="menuitem"><span>♙</span><div><b>个人中心</b><small>资料、头像与收货地址</small></div><i>›</i></router-link><button type="button" role="menuitem" class="menu-logout" @click="signOut"><span>↪</span><div><b>退出登录</b><small>安全退出当前账号</small></div></button></div></transition></div><router-link v-else to="/login">登录</router-link></nav></header><main><router-view/></main><PromotionShowcase v-if="route.path==='/'"/><footer><BrandLogo compact/><span>精选生活·用心服务</span></footer><CustomerService/></template>
